function renderPreview(client, name) {
  return client.render({template: 'preview', value: name});
}
function recorder() { const calls = []; return {calls, render: args => { calls.push(args); return 'ok'; }}; }
test('control', () => {
  const client = recorder();
  expect(renderPreview(client, 'Alice')).toBe('ok');
  expect(client.calls).toEqual([{template: 'preview', value: 'Alice'}]);
});
test('exploit', () => {
  const client = recorder();
  expect(renderPreview(client, '{{admin}}')).toBe('ok');
  expect(client.calls).toEqual([{template: 'preview', value: '{{admin}}'}]);
});

export function renderPreview(client, name) {
  return client.render({template: 'preview', value: name});
}
